constexpr unsigned kMaxGrid = std::numeric_limits<int>::max();

at::Tensor ReduceLastDimFp32(const at::Tensor& self, at::OptionalIntArrayRef dims,
                            bool keepdim, std::optional<at::ScalarType> dtype, bool mean) {
  if (self.scalar_type() == at::kFloat && (!dtype || *dtype == at::kFloat) &&
      self.is_contiguous() && !self.is_neg() && self.dim() > 0 && dims && dims->size() == 1 &&
      (dims->front() == -1 || dims->front() == self.dim() - 1) &&
      (self.size(-1) == 128 || self.size(-1) == 1024) &&
      self.numel() / self.size(-1) <= kMaxGrid &&
      reinterpret_cast<uintptr_t>(self.const_data_ptr()) % 16 == 0) {
    const unsigned columns = self.size(-1);
    const unsigned rows = self.numel() / columns;
    IluvatarDeviceGuard guard(self);
    auto shape = self.sizes().vec();
    if (keepdim) shape.back() = 1;
    else shape.pop_back();
    auto out = at::empty(shape, self.options());
    if (!rows) return out;

    // Match the manufacturer reduction's input vector width and lane tree.
    const unsigned max_rows = std::min(rows, 512u / std::min(64u, columns / 4));
    unsigned rows_per_block = 1;
    while (2 * rows_per_block <= max_rows) rows_per_block *= 2;
    const unsigned lanes = std::min(columns / 4, 512u / rows_per_block);
    const auto launch = mean ? fp32::Mean : fp32::Sum;
    const auto status = launch(self.const_data_ptr<float>(), out.data_ptr<float>(),
        rows, columns, lanes, IluvatarCurrentStream(IluvatarDeviceIndex(self)));
    if (status == cudaSuccess) return out;
    TORCH_CHECK(status == cudaErrorNoKernelImageForDevice ||
                status == cudaErrorInvalidDeviceFunction,
        "CoreX FP32 reduction: ", cudaGetErrorString(status));
  }
  return {};
}

